def transform(grid):
    out = [row[:] for row in grid]
    first = grid[0]
    period = next((p for p in range(1, len(first) + 1)
                   if all(first[i] == first[i % p] for i in range(len(first)))), len(first))
    seq = first[:period]
    for r, row in enumerate(out):
        for c, value in enumerate(row):
            if value != 0:
                continue
            if r == 0 or c < r:
                row[c] = seq[c % period] if r == 0 else seq[(c + 1) % period]
            elif c == r:
                row[c] = seq[r % period]
            else:
                row[c] = seq[c % period]
    return out
